'use client';

import { ReactNode, useEffect } from 'react';
import { X } from 'lucide-react';

interface ModalProps {
  open: boolean;
  title: string;
  children: ReactNode;
  primaryLabel?: string;
  secondaryLabel?: string;
  onPrimary?: () => void;
  onSecondary?: () => void;
  onClose?: () => void;
}

export default function Modal({
  open,
  title,
  children,
  primaryLabel = 'Allow',
  secondaryLabel = 'Not now',
  onPrimary,
  onSecondary,
  onClose,
}: ModalProps) {
  useEffect(() => {
    if (!open) {
      return;
    }

    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        onClose?.();
      }
    };

    document.addEventListener('keydown', onKeyDown);
    return () => document.removeEventListener('keydown', onKeyDown);
  }, [open, onClose]);

  if (!open) {
    return null;
  }

  return (
    <div
      className="mr-modal-backdrop"
      role="presentation"
      onMouseDown={(event) => {
        if (event.target === event.currentTarget) {
          onClose?.();
        }
      }}
    >
      <section className="mr-modal" role="dialog" aria-modal="true" aria-labelledby="mr-modal-title">
        {onClose ? (
          <button
            aria-label="Close modal"
            onClick={onClose}
            style={{
              position: 'absolute',
              width: 1,
              height: 1,
              padding: 0,
              margin: -1,
              overflow: 'hidden',
              clip: 'rect(0, 0, 0, 0)',
              whiteSpace: 'nowrap',
              border: 0,
            }}
          >
            <X size={16} />
          </button>
        ) : null}
        <h2 id="mr-modal-title" className="mr-modal-title">
          {title}
        </h2>
        <div className="mr-modal-body">{children}</div>
        <div className="mr-modal-actions">
          <button type="button" className="mr-modal-btn-secondary" onClick={onSecondary ?? onClose}>
            {secondaryLabel}
          </button>
          <button type="button" className="mr-modal-btn-primary" onClick={onPrimary}>
            {primaryLabel}
          </button>
        </div>
      </section>
    </div>
  );
}

'use client';

interface StepIndicatorProps {
  currentStep: number;
  totalSteps?: number;
}

export default function StepIndicator({ currentStep, totalSteps = 4 }: StepIndicatorProps) {
  return (
    <div className="mr-step-dots" aria-label={`Step ${currentStep} of ${totalSteps}`}>
      {Array.from({ length: totalSteps }, (_, index) => {
        const step = index + 1;
        const stateClass = step === currentStep ? ' active' : step < currentStep ? ' done' : '';

        return <span key={step} className={`mr-step-dot${stateClass}`} aria-hidden="true" />;
      })}
    </div>
  );
}

'use client';

interface ToggleProps {
  checked: boolean;
  onChange: (checked: boolean) => void;
  label?: string;
  description?: string;
  disabled?: boolean;
}

export default function Toggle({ checked, onChange, label, description, disabled = false }: ToggleProps) {
  const toggle = () => {
    if (!disabled) {
      onChange(!checked);
    }
  };

  return (
    <div className="mr-toggle-wrapper">
      {(label || description) && (
        <div style={{ paddingRight: 16 }}>
          {label ? <div className="mr-title-sm">{label}</div> : null}
          {description ? (
            <div className="mr-body-sm" style={{ color: 'var(--gray-500)', marginTop: 2 }}>
              {description}
            </div>
          ) : null}
        </div>
      )}
      <button
        type="button"
        role="switch"
        aria-checked={checked}
        aria-label={label}
        disabled={disabled}
        onClick={toggle}
        className={`mr-toggle-track${checked ? ' active' : ''}`}
        style={{
          border: 0,
          opacity: disabled ? 0.55 : 1,
        }}
      >
        <span className="mr-toggle-thumb" />
      </button>
    </div>
  );
}

