            <span className="min-w-0 flex-1 truncate text-[15px] font-bold text-slate-950">{entry.name}</span>
            <span className="text-[13px] font-black text-[#003B73]">{entry.cases} Cases</span>
          </div>
        ))}
      </section>
    </div>
  );
}

'use client';

import { useMemo, useState } from 'react';
import { HeartPulse, MapPin, Search } from 'lucide-react';
import { mockAEDs } from '@/app/myResponder/data/mockAEDs';

export default function FindAEDsPage() {
  const [query, setQuery] = useState('');
  const filtered = useMemo(() => {
    const needle = query.trim().toLowerCase();
    if (!needle) {
      return mockAEDs.slice(0, 8);
    }

    return mockAEDs.filter((aed) => `${aed.name} ${aed.address}`.toLowerCase().includes(needle)).slice(0, 8);
  }, [query]);

  return (
    <div className="mr-page mr-animate-fade-in bg-[#EEF2F6]">
      <header className="mr-header">
        <h1 className="mr-header-title">Find AEDs</h1>
      </header>
      <section className="shrink-0 px-4 pt-4">
        <label className="flex items-center gap-3 rounded-2xl bg-white px-4 py-3 shadow-xs">
          <Search size={19} className="text-slate-400" />
          <input
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            placeholder="Search for AEDs"
            className="min-w-0 flex-1 bg-transparent text-[15px] font-semibold outline-none placeholder:text-slate-400"
          />
        </label>
      </section>

      <section className="mx-4 mt-4 h-[250px] shrink-0 overflow-hidden rounded-[26px] border border-slate-100 bg-[#DDEAD8] shadow-xs">
        <div className="relative h-full w-full bg-[linear-gradient(135deg,#d9ead3_0%,#d9ead3_45%,#cfe3ef_45%,#cfe3ef_55%,#d9ead3_55%)]">
          <div className="absolute inset-x-0 top-1/2 h-8 -translate-y-1/2 bg-white/45" />
          <div className="absolute inset-y-0 left-1/2 w-8 -translate-x-1/2 bg-white/45" />
          {mockAEDs.slice(0, 12).map((aed, index) => (
            <button
              type="button"
              key={aed.id}
              className="absolute grid h-8 w-8 place-items-center rounded-full border-2 border-white bg-[#43A047] text-white shadow-md"
              style={{
                left: `${12 + ((index * 23) % 72)}%`,
                top: `${14 + ((index * 31) % 68)}%`,
              }}
              title={aed.name}
            >
              <HeartPulse size={16} fill="currentColor" />
            </button>
          ))}
        </div>
      </section>

      <section className="space-y-3 px-4 py-4">
        {filtered.map((aed) => (
          <div key={aed.id} className="flex gap-3 rounded-2xl bg-white p-4 shadow-xs">
            <span className="grid h-11 w-11 shrink-0 place-items-center rounded-xl bg-green-50 text-[#43A047]">
              <HeartPulse size={22} />
            </span>
            <span className="min-w-0 flex-1">
              <span className="block text-[15px] font-black text-slate-950">{aed.name}</span>
              <span className="mt-1 flex items-start gap-1 text-[12px] font-semibold leading-snug text-slate-500">
                <MapPin size={13} className="mt-0.5 shrink-0" />
                {aed.floor ? `${aed.floor} • ` : ''}{aed.address}
              </span>
            </span>
          </div>
        ))}
      </section>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { AlertTriangle, HeartPulse, MessageSquare, Smartphone, Send } from 'lucide-react';

const categories = [
  { label: 'Fire hazard', icon: AlertTriangle, color: '#FF9800' },
  { label: 'AED fault', icon: HeartPulse, color: '#43A047' },
  { label: 'App issue', icon: Smartphone, color: '#003B73' },
  { label: 'General', icon: MessageSquare, color: '#64748B' },
];

export default function FeedbackPage() {
  const [selected, setSelected] = useState(categories[0].label);
  const [message, setMessage] = useState('');
  const [sent, setSent] = useState(false);

  return (
    <div className="mr-page mr-animate-fade-in bg-[#EEF2F6]">
      <header className="mr-header">
        <h1 className="mr-header-title">Feedback</h1>
      </header>
      <section className="mr-page-content">
        <div className="rounded-[28px] bg-[#003B73] p-5 text-white shadow-md">
          <p className="text-[12px] font-black uppercase tracking-wide text-white/55">Support</p>
          <h2 className="mt-2 text-[27px] font-black leading-tight">Hey there! We&apos;re here to help</h2>
          <p className="mt-2 text-[14px] font-semibold leading-relaxed text-white/75">
            Select a category and tell us what happened.
          </p>
        </div>

        <div className="mt-4 grid grid-cols-2 gap-3">
          {categories.map((category) => {
            const Icon = category.icon;
            const active = selected === category.label;
            return (
              <button
                key={category.label}
                type="button"
                onClick={() => setSelected(category.label)}
                className={`rounded-2xl border-2 bg-white p-4 text-left shadow-xs ${active ? 'border-[#003B73]' : 'border-slate-100'}`}
              >
                <span className="grid h-10 w-10 place-items-center rounded-xl" style={{ background: `${category.color}14`, color: category.color }}>
                  <Icon size={22} />
                </span>
                <span className="mt-3 block text-[14px] font-black text-slate-950">{category.label}</span>
              </button>
            );
          })}
        </div>

        <div className="mt-4 rounded-2xl bg-white p-4 shadow-xs">
          <label className="mr-input-label" htmlFor="feedback">Message</label>
          <textarea
            id="feedback"
            value={message}
            onChange={(event) => setMessage(event.target.value)}
            placeholder="Describe the issue or suggestion..."
            className="min-h-[120px] w-full resize-none rounded-xl border border-slate-200 p-3 text-[15px] outline-none focus:border-[#003B73]"
          />
        </div>

        {sent ? (
          <div className="mt-4 rounded-2xl bg-green-50 p-4 text-[14px] font-bold text-green-700">
            Thank you. Your {selected.toLowerCase()} feedback has been recorded.
          </div>
        ) : null}
      </section>
      <footer className="shrink-0 border-t border-slate-100 bg-white p-4">
        <button className="mr-btn mr-btn-primary" type="button" onClick={() => setSent(true)}>
          <Send size={18} />
          Submit feedback
        </button>
      </footer>
    </div>
  );
}

